  const body = await c.req.json<CreateDispatchRequest>().catch(() => null)
  if (!body || (!body.repo && !body.org)) {
    return c.json({ error: "Invalid dispatch request" }, 400)
  }

  const userId = c.get("userId")
  const db = getDb(c.env)

  if (body.repo) {
    const repoAccess = await checkRepoAccess(db, body.repo, userId, { requireRepo: true })
    if (repoAccess instanceof Response) {
      return repoAccess
    }
  }

  const record = await buildDispatchRecord(db, userId, body)
  if (!record) {
    return c.json({ error: "Invalid dispatch request" }, 400)
  }

  record.web_url = `${c.env.FRONTEND_BASE_URL}/dispatches/${record.id}`

  if (!body.dry_run) {
    const existingIds = await readUserDispatchIds(c.env.ENTIRE_CACHE, userId)
    await Promise.all([
      c.env.ENTIRE_CACHE.put(dispatchDetailKey(record.id), JSON.stringify(record)),
      writeUserDispatchIds(c.env.ENTIRE_CACHE, userId, [record.id, ...existingIds]),
